//! 🖨️ Literal Raster relational domains, native controls and actual declaration I/O.
use super::*;
fn provider()->store::ArtifactSqliteSnapshotCodec{<RasterSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().expect("Raster must declare its complete owned semantic SQLite capability")}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_raster_actual_declaration_capability(){semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("raster").label("Raster owned SQLite").version("0.0.1").package_id("semio:raster").artifact(crate::declaration().unwrap()).try_build().unwrap();let codec=store::document_codec(RASTER_DOCUMENT_SCHEMA).await.unwrap().unwrap();let p=codec.snapshot_sqlite.expect("actual Raster declaration must publish semantic SQLite");assert_eq!(p.snapshot_type,Some(std::any::TypeId::of::<RasterSnapshot>()));
 use store::io::io_mechanism::{io_route,io_run};
 let dialect=dialect();let sqlite=store::io_schema::ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT);
 let into=io_route(&dialect,&sqlite,1).await.unwrap().value;let from=io_route(&sqlite,&dialect,1).await.unwrap().value;
 let owner=neutral();for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let input=payload(owner.0.as_ref().unwrap(),encoding);let exported=io_run(&into,input.clone()).await.unwrap().value;let store::io_schema::IoPayload::Binary(bytes)=&exported else{panic!("SQLite file carrier")};assert_eq!(&bytes[..16],b"SQLite format 3\0");assert_eq!(io_run(&from,exported).await.unwrap().value,input);}
}
#[test]
fn sqlite_snapshot_raster_both_native_encodings_and_literal_child_identity(){let p=provider();let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let d=store::os_io::ArtifactDialect{artifact_kind:"s.raster.raster".into(),standard:"1".into(),subset:"*".into()};for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let mut s=RasterSnapshot::default();s.schema=fixture["schema"].as_str().unwrap().into();s.id=fixture["id"].as_str().unwrap().into();s.title=Some(String::new());let child=&fixture["child"];let target=&child["target"];let dialect=&target["dialect"];s.assets.insert(String::new(),store::ArtifactChild::new(child["childId"].as_str().unwrap().into(),store::os_io::ArtifactRef{artifact_id:target["artifactId"].as_str().unwrap().into(),dialect:store::os_io::ArtifactDialect{artifact_kind:dialect["artifactKind"].as_str().unwrap().into(),standard:dialect["standard"].as_str().unwrap().into(),subset:dialect["subset"].as_str().unwrap().into()}})).map_err(|e|e.reason).unwrap();let payload=match encoding{store::sqlite_snapshot::SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),store::sqlite_snapshot::SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};let result=(p.export)(RASTER_DOCUMENT_SCHEMA,&d,&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default()));retire_raster_snapshot(s);let database=result.unwrap().value;assert_eq!(database.table("raster_asset").unwrap().rows.len(),1);let result=(p.import)(RASTER_DOCUMENT_SCHEMA,&d,database,encoding,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;let restored:RasterSnapshot=match result{store::os_io::IoPayload::Binary(bytes)=>store::ArtifactPack::decode_pack(&bytes).unwrap(),store::os_io::IoPayload::Text(text)=>store::ArtifactDsl::parse_dsl(&text).unwrap()};assert_eq!(restored.assets.iter().next().unwrap().1.target.artifact_id,"\0");retire_raster_snapshot(restored);}}
#[test]
fn sqlite_snapshot_raster_controlled_owner_refusals(){let p=provider();let s=RasterSnapshot::default();let payload=store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s));retire_raster_snapshot(s);let d=store::os_io::ArtifactDialect{artifact_kind:"s.raster.raster".into(),standard:"1".into(),subset:"*".into()};assert!((p.export)(RASTER_DOCUMENT_SCHEMA,&d,&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|false,Default::default())).is_err());let foreign=store::os_io::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),..d};assert!((p.export)(RASTER_DOCUMENT_SCHEMA,&foreign,&payload,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn transform(v:&serde_json::Value)->RasterTransform{RasterTransform{x:v["x"].as_f64().unwrap(),y:v["y"].as_f64().unwrap(),a:v["a"].as_f64().unwrap(),b:v["b"].as_f64().unwrap(),c:v["c"].as_f64().unwrap(),d:v["d"].as_f64().unwrap()}}
fn intrinsic(v:&serde_json::Value)->semio_framework_value::DslValue{match v["kind"].as_str().unwrap(){"null"=>semio_framework_value::DslValue::Null,"boolean"=>semio_framework_value::DslValue::Bool(v["value"].as_bool().unwrap()),"signed"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::Int(v["value"].as_str().unwrap().parse().unwrap())),"unsigned"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::UInt(v["value"].as_str().unwrap().parse().unwrap())),"float"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::Float(f64::from_bits(u64::from_str_radix(v["value"].as_str().unwrap(),16).unwrap()))),"text"=>semio_framework_value::DslValue::String(v["value"].as_str().unwrap().into()),"bytes"=>semio_framework_value::DslValue::Bytes(v["value"].as_array().unwrap().iter().map(|v|u8::try_from(v.as_u64().unwrap()).unwrap()).collect()),"array"=>semio_framework_value::DslValue::Array(v["items"].as_array().unwrap().iter().map(intrinsic).collect()),"object"=>semio_framework_value::DslValue::Object(v["members"].as_array().unwrap().iter().map(|v|(v["name"].as_str().unwrap().into(),intrinsic(&v["value"]))).collect()),_=>panic!("neutral intrinsic variant")}}
struct Owner(Option<RasterSnapshot>);
impl Drop for Owner{fn drop(&mut self){if let Some(s)=self.0.take(){super::sqlite::retire_snapshot(s)}}}
fn neutral()->Owner{let f=fixture();let m=&f["mask"];let mask=RasterLayerMask{enabled:m["enabled"].as_bool().unwrap(),linked:m["linked"].as_bool().unwrap(),invert:m["invert"].as_bool().unwrap(),width:Some(u32::MAX),height:Some(0),image_key:Some(m["imageKey"].as_str().unwrap().into()),transform:transform(&m["transform"])};let mut s=RasterSnapshot::default();s.schema=f["schema"].as_str().unwrap().into();s.id=f["id"].as_str().unwrap().into();s.title=Some(String::new());s.layers.push(RasterLayerNode::Pixel{id:String::new(),name:"literal name\0".into(),visible:false,locked:true,opacity:0.5,blend_mode:"arbitrary!".into(),transform:transform(&f["transform"]),mask:Some(mask),width:Some(u32::MAX),height:Some(0),image_key:Some(String::new())});s.layers.push(RasterLayerNode::Group{id:String::new(),name:"literal name\0".into(),visible:false,locked:true,opacity:0.5,blend_mode:"arbitrary!".into(),transform:transform(&f["transform"]),mask:None,children:vec![RasterLayerNode::Group{id:String::new(),name:"literal name\0".into(),visible:false,locked:true,opacity:0.5,blend_mode:"arbitrary!".into(),transform:transform(&f["transform"]),mask:None,children:Vec::new()}]});let mut params=RasterOwnedMap::new();params.insert(String::new(),intrinsic(&f["parameter"])).map_err(|e|e.reason).unwrap();s.layers.push(RasterLayerNode::Adjustment{id:String::new(),name:"literal name\0".into(),visible:false,locked:true,opacity:0.5,blend_mode:"arbitrary!".into(),transform:transform(&f["transform"]),adjustment_kind:"private effect".into(),params});let c=&f["child"];let d=&c["target"]["dialect"];s.assets.insert(String::new(),store::ArtifactChild::new(c["childId"].as_str().unwrap().into(),store::io_schema::ArtifactRef{artifact_id:c["target"]["artifactId"].as_str().unwrap().into(),dialect:store::io_schema::ArtifactDialect{artifact_kind:d["artifactKind"].as_str().unwrap().into(),standard:d["standard"].as_str().unwrap().into(),subset:d["subset"].as_str().unwrap().into()}})).map_err(|e|e.reason).unwrap();Owner(Some(s))}
fn dialect()->store::io_schema::ArtifactDialect{store::io_schema::ArtifactDialect{artifact_kind:"s.raster.raster".into(),standard:"1".into(),subset:"*".into()}}
fn payload(s:&RasterSnapshot,encoding:store::sqlite_snapshot::SnapshotEncoding)->store::io_schema::IoPayload{match encoding{store::sqlite_snapshot::SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(s)),store::sqlite_snapshot::SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(s))}}
fn decode(payload:store::io_schema::IoPayload)->Owner{Owner(Some(match payload{store::io_schema::IoPayload::Binary(bytes)=>store::ArtifactPack::decode_pack(&bytes).unwrap(),store::io_schema::IoPayload::Text(text)=>store::ArtifactDsl::parse_dsl(&text).unwrap()}))}
#[test]
fn sqlite_snapshot_raster_full_owned_entities_and_raw_words_both_encodings(){let f=fixture();for(i,word)in f["float64Words"].as_array().unwrap().iter().enumerate(){let mut owner=neutral();let s=owner.0.as_mut().unwrap();let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Words"][i].as_str().unwrap(),16).unwrap();let RasterLayerNode::Pixel{opacity,transform,..}=&mut s.layers[0]else{panic!("neutral pixel")};*opacity=f32::from_bits(bits32);transform.x=f64::from_bits(bits);
 for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let p=provider();let database=(p.export)(RASTER_DOCUMENT_SCHEMA,&dialect(),&payload(s,encoding),&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;let row=&database.table("raster_layer").unwrap().rows[0];let scalar=database.table("raster_scalar32").unwrap().rows.iter().find(|v|v.rowid==row.integer(9).unwrap()).unwrap();assert_eq!(u32::try_from(scalar.integer(2).unwrap()).unwrap(),bits32);let result=(p.import)(RASTER_DOCUMENT_SCHEMA,&dialect(),database,encoding,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;let restored=decode(result);let r=restored.0.as_ref().unwrap();let RasterLayerNode::Pixel{opacity,transform,width,height,image_key,mask,..}=&r.layers[0]else{panic!("restored pixel")};assert_eq!(opacity.to_bits(),bits32);assert_eq!(transform.x.to_bits(),bits);assert_eq!((*width,*height,image_key.as_deref()),(Some(u32::MAX),Some(0),Some("")));assert_eq!(mask.as_ref().unwrap().height,Some(0));assert_eq!(r.schema,s.schema);assert_eq!(r.assets.iter().next().unwrap().1.target,s.assets.iter().next().unwrap().1.target);let RasterLayerNode::Adjustment{params,..}=&r.layers[2]else{panic!("restored adjustment")};let semio_framework_value::DslValue::Object(members)=params.get("").unwrap()else{panic!("neutral ordered intrinsic")};assert_eq!(members.iter().map(|v|v.0.as_str()).collect::<Vec<_>>(),["duplicate","duplicate",""]);
 }
 }}
#[test]
fn sqlite_snapshot_raster_schema_relationships_and_exact_row_bound(){use store::ArtifactSqliteSnapshot;let owner=neutral();let s=owner.0.as_ref().unwrap();let database=s.to_sqlite_database(&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let count=database.tables.iter().map(|v|v.rows.len()).sum();let limits=store::sqlite_snapshot::SqliteDatabaseLimits{max_rows:count,..Default::default()};assert!(s.to_sqlite_database(&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok());let restored=Owner(Some(RasterSnapshot::from_sqlite_database(&database,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap()));assert_eq!(restored.0.as_ref().unwrap().layers.len(),3);let mut missing=database.clone();missing.table_mut("raster_pixel").unwrap().rows.clear();assert!(RasterSnapshot::from_sqlite_database(&missing,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());let mut orphan=database.clone();let row=orphan.table_mut("raster_group").unwrap();row.rows.push(store::sqlite_snapshot::SqliteRow{rowid:999,values:vec![store::sqlite_snapshot::SqliteValue::Integer(999)]});assert!(RasterSnapshot::from_sqlite_database(&orphan,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());let mut weak=database;let sql=weak.table("raster_document").unwrap().sql.replace("TEXT NOT NULL","TEXT");weak.table_mut("raster_document").unwrap().sql=sql;assert!(RasterSnapshot::from_sqlite_database(&weak,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}
#[test]
fn sqlite_snapshot_raster_four_phases_interior_large_copy_cancellation(){use store::ArtifactSqliteSnapshot;let f=fixture();let length=f["intrinsicBytes"].as_u64().unwrap()as usize;for text in [false,true]{let mut owner=neutral();let s=owner.0.as_mut().unwrap();let RasterLayerNode::Adjustment{params,..}=&mut s.layers[2]else{panic!("neutral adjustment")};let value=if text{semio_framework_value::DslValue::String("x".repeat(length))}else{semio_framework_value::DslValue::Bytes(vec![7;length])};let previous=std::mem::replace(params.get_mut("").unwrap(),value);<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(previous);let database=s.to_sqlite_database(&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();
 for phase in [store::sqlite_snapshot::SqliteSnapshotPhase::ProjectSnapshot,store::sqlite_snapshot::SqliteSnapshotPhase::ReconstructSnapshot]{let mut observed=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}};let mut control=store::sqlite_snapshot::SqliteSnapshotControl::new(&mut callback,Default::default());match phase{store::sqlite_snapshot::SqliteSnapshotPhase::ProjectSnapshot=>assert!(s.to_sqlite_database(&mut control).is_err()),store::sqlite_snapshot::SqliteSnapshotPhase::ReconstructSnapshot=>assert!(RasterSnapshot::from_sqlite_database(&database,&mut control).is_err()),_=>unreachable!()}assert!(observed,"typed copy phase {phase:?}");}
 for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let input=payload(s,encoding);for phase in [store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative]{let mut observed=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=65536&&event.completed<event.total{observed=true;false}else{true}};let mut control=store::sqlite_snapshot::SqliteSnapshotControl::new(&mut callback,Default::default());if phase==store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative{assert!(RasterSnapshot::decode_sqlite_snapshot_native(&input,&mut control).is_err());}else{assert!(s.encode_sqlite_snapshot_native(encoding,&mut control).is_err());}assert!(observed,"native copy phase {phase:?} {encoding:?}");}}
 }}
#[test]
fn sqlite_snapshot_raster_deep_flat_native_ownership_and_late_refusal(){std::thread::Builder::new().stack_size(256*1024).spawn(||{use store::ArtifactSqliteSnapshot;let mut owner=neutral();let s=owner.0.as_mut().unwrap();let RasterLayerNode::Adjustment{params,..}=&mut s.layers[2]else{panic!("neutral adjustment")};let mut value=semio_framework_value::DslValue::String("deep literal".into());for _ in 0..1024{value=semio_framework_value::DslValue::Array(vec![value]);}let previous=std::mem::replace(params.get_mut("").unwrap(),value);<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(previous);params.insert("z".into(),semio_framework_value::DslValue::String("x".repeat(100000))).map_err(|e|e.reason).unwrap();
 for encoding in [store::sqlite_snapshot::SnapshotEncoding::Binary,store::sqlite_snapshot::SnapshotEncoding::Text]{let input=payload(s,encoding);let decoded=Owner(Some(RasterSnapshot::decode_sqlite_snapshot_native(&input,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap()));let r=decoded.0.as_ref().unwrap();let RasterLayerNode::Adjustment{params,..}=&r.layers[2]else{panic!("deep adjustment")};let mut value=params.get("").unwrap();let mut depth=0;while let semio_framework_value::DslValue::Array(items)=value{assert_eq!(items.len(),1);value=&items[0];depth+=1;}assert_eq!(depth,1024);let database=r.to_sqlite_database(&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let mut late=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==store::sqlite_snapshot::SqliteSnapshotPhase::ReconstructSnapshot&&event.completed>=65536&&event.completed<event.total{late=true;false}else{true}};assert!(RasterSnapshot::from_sqlite_database(&database,&mut store::sqlite_snapshot::SqliteSnapshotControl::new(&mut callback,Default::default())).is_err());assert!(late);}
 }).unwrap().join().unwrap();}

#[test]
fn sqlite_snapshot_raster_cold_retirement_releases_atomic_large_strings(){
 let count=usize::try_from(fixture()["intrinsicBytes"].as_u64().unwrap()).unwrap();
 let mut owner=neutral();let snapshot=owner.0.as_mut().unwrap();snapshot.schema="x".repeat(count);snapshot.id="y".repeat(count);
 let RasterLayerNode::Adjustment{params,..}=&mut snapshot.layers[2]else{panic!("neutral adjustment")};
 let previous=std::mem::replace(params.get_mut("").unwrap(),semio_framework_value::DslValue::String("z".repeat(count)));<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(previous);
 drop(owner);
}
